<script lang="ts">
  import {refreshAll} from '$app/navigation';
  import type {AppData,Row} from '#lib/client/types.ts';
  import {display,recordName} from '#lib/client/api.ts';
  import {currencyAmount} from '#lib/client/finance.ts';
  import Icon from './Icon.svelte';
  import Status from './Status.svelte';
  let {data}:{data:AppData}=$props();
  const slug=$derived(data.module?.slug||'');const record=$derived(data.detail||{});
  const transactions=$derived(data.related?.bank_transactions||[]);
  const exportItems=$derived(data.related?.datev_export_items||[]);
  const dunningEvents=$derived(data.related?.dunning_events||[]);
  const packageUrl=$derived(data.summary?.packageDownloadUrl||(record.document_id&&slug==='datev'?`/api/v1/documents/${record.document_id}/download`:null));
  const financialSlugs=['receivables','payables','bank-accounts','bank-imports','bank-transactions','credit-offsets','dunning','datev'];
  function sourceName(item:Row){return item.document_number||item.invoice_number||item.snapshot?.number||item.snapshot?.invoice?.number||item.snapshot?.invoice_number||'Beleg';}
  function sourceUrl(item:Row){return item.invoice_id?`/invoices/${item.invoice_id}`:item.supplier_invoice_id?`/supplier-invoices/${item.supplier_invoice_id}`:item.payment_id?`/payments/${item.payment_id}`:undefined;}
</script>
{#if financialSlugs.includes(slug)}
  {#if slug==='receivables'||slug==='payables'}<section class="panel"><header class="panel-header"><h2>{slug==='receivables'?'Bestätigter Forderungsstand':'Bestätigte Verbindlichkeit'}</h2></header><div class="panel-body"><dl class="definition-list"><div><dt>Geschäftspartner</dt><dd>{record.party_name||display(record.party_id,'party_id',data)}</dd></div><div><dt>Beleg</dt><dd>{#if record.invoice_id}<a class="text-link" href={`/${slug==='receivables'?'invoices':'supplier-invoices'}/${record.invoice_id}`}>{record.document_number||record.invoice_number||'Ursprünglichen Beleg öffnen'}<Icon name="arrow" size={14}/></a>{:else}—{/if}</dd></div><div><dt>Ursprünglicher Betrag</dt><dd>{currencyAmount(record.original_amount,record.currency)}</dd></div><div><dt>Aktuell offen</dt><dd><strong>{currencyAmount(record.open_amount,record.currency)}</strong></dd></div><div><dt>Fälligkeit</dt><dd>{display(record.due_date,'date')}</dd></div><div><dt>Strittigkeit / Mahnsperre</dt><dd>{record.disputed?'Strittig · nicht automatisiert mahnen':'Keine Strittigkeit vermerkt'}</dd></div></dl><p class="field-help mt">Der offene Betrag berücksichtigt bestätigte Zahlungen und gebuchte Verrechnungen. Maßgeblich bleibt der ursprüngliche, unveränderte Beleg.</p></div></section>
  {:else if slug==='bank-accounts'}<section class="panel"><header class="panel-header"><h2>Nachgewiesene Bankverbindung</h2></header><div class="panel-body"><dl class="definition-list"><div><dt>Kontoinhaber</dt><dd>{record.holder||record.bank_holder||'—'}</dd></div><div><dt>IBAN</dt><dd>{record.iban||'—'}</dd></div><div><dt>BIC</dt><dd>{record.bic||'—'}</dd></div><div><dt>Bestätigt am</dt><dd>{display(record.verified_at,'verified_at')}</dd></div><div><dt>Gültig ab</dt><dd>{display(record.valid_from,'date')}</dd></div></dl><p class="field-help mt">Diese Ansicht zeigt einen bestätigten Kontostand. Änderungen an der eigenen Bankverbindung werden mit persönlicher Passwortbestätigung in den Betriebseinstellungen dokumentiert.</p></div></section>
  {:else if slug==='bank-transactions'}<section class="panel"><header class="panel-header"><h2>Originale Kontobuchung prüfen</h2><Status value={record.status}/></header><div class="panel-body"><dl class="definition-list"><div><dt>Gegenpartei laut Auszug</dt><dd>{record.counterparty||'Nicht im Auszug angegeben'}</dd></div><div><dt>Betrag laut Auszug</dt><dd><strong>{currencyAmount(record.amount,record.currency)}</strong></dd></div><div><dt>Buchungstag</dt><dd>{display(record.booking_date,'date')}</dd></div><div><dt>Wertstellung</dt><dd>{display(record.value_date,'date')}</dd></div><div class="full"><dt>Verwendungszweck</dt><dd>{record.reference||'Nicht im Auszug angegeben'}</dd></div>{#if record.counterparty_iban}<div class="full"><dt>IBAN laut Auszug</dt><dd>{record.counterparty_iban}</dd></div>{/if}</dl>{#if record.payment_id}<a class="btn mt" href={`/payments/${record.payment_id}`}>Gebuchte Zahlung öffnen<Icon name="arrow" size={15}/></a>{:else}<p class="field-help mt">Der Eintrag ist noch keine gebuchte Zahlung. Über „Als Zahlung übernehmen“ prüfen Sie Geschäftspartner, offenen Beleg und etwaige Dubletten.</p>{/if}{#if record.duplicate_of_id}<div class="notice warning mt"><Icon name="alert"/><div>Eine mögliche Dublette wurde erkannt. Vergleichen Sie den Originalauszug und die bereits vorhandene Buchung, bevor Sie diese Position übernehmen.</div></div>{/if}</div></section>
  {:else if slug==='credit-offsets'}<section class="panel"><header class="panel-header"><h2>Gebuchter Verrechnungsnachweis</h2></header><div class="panel-body"><dl class="definition-list"><div><dt>Geschäftspartner</dt><dd>{record.party_name||display(record.party_id,'party_id',data)}</dd></div><div><dt>Verrechneter Betrag</dt><dd>{currencyAmount(record.amount,record.currency)}</dd></div>{#each [{key:'positive_id',label:'Positiver offener Beleg'},{key:'negative_id',label:'Verrechnete Gutschrift'}] as field}<div><dt>{field.label}</dt><dd><a class="text-link" href={`/${record.target_kind==='payable'?'payables':'receivables'}/${record[field.key]}`}>{display(record[field.key],field.key,data)}<Icon name="arrow" size={14}/></a></dd></div>{/each}<div class="full"><dt>Vereinbarung / Grundlage</dt><dd>{record.reason||'—'}</dd></div></dl></div></section>
  {/if}
  {#if slug==='bank-imports'}<section class="panel"><header class="panel-header"><div><h2>Kontobuchungen aus diesem Auszug</h2><p>Jede Position wird einzeln geprüft und erst danach als Zahlung übernommen.</p></div><span class="count">{transactions.length}</span></header>{#if transactions.length}<div class="bank-transaction-list">{#each transactions as transaction}<a class="bank-transaction" href={`/bank-transactions/${transaction.id}`}><div><strong>{transaction.counterparty||transaction.reference||'Kontobuchung'}</strong><p class="small muted">{display(transaction.booking_date,'date')} · {transaction.reference||'Ohne Verwendungszweck'}</p>{#if transaction.duplicate_of_id}<p class="field-help">Mögliche Dublette · bewusst prüfen</p>{/if}<Status value={transaction.status}/></div><div class="bank-transaction-total"><strong>{currencyAmount(transaction.amount,transaction.currency)}</strong><Icon name="chevron" size={17}/></div></a>{/each}</div>{:else}<div class="empty-state compact"><Icon name="file" size={25}/><h3>{['processing','queued','running'].includes(record.status)?'Kontobuchungen werden eingelesen':'Noch keine Kontobuchungen eingelesen'}</h3><p>{['processing','queued','running'].includes(record.status)?'Der bestätigte Auszug wird im Hintergrund geprüft und eingelesen. Es wurde noch keine Zahlung gebucht.':'Prüfen Sie das private Original und das bestätigte Konto. Anschließend können Sie den Auszug zur Prüfung einlesen.'}</p>{#if ['processing','queued','running'].includes(record.status)}<button class="btn" onclick={()=>refreshAll()}><Icon name="refresh" size={15}/>Verarbeitungsstand aktualisieren</button>{/if}</div>{/if}</section>{/if}
  {#if slug==='datev'}<section class="panel"><header class="panel-header"><div><h2>Übergabepaket für die Kanzlei</h2><p>Geprüfter Buchungsstapel und die zugehörigen Originalnachweise.</p></div></header><div class="panel-body">{#if packageUrl}<a class="btn primary" href={packageUrl} data-sveltekit-reload download><Icon name="download" size={16}/>DATEV-Paket als ZIP herunterladen</a><p class="field-help mt">Prüfen Sie den Kanzlei-Import anschließend. Erst die ausdrückliche Importbestätigung kennzeichnet die Übergabe als abgeschlossen.</p>{:else}<p class="small">Das ZIP-Paket ist noch nicht verfügbar. Erzeugen Sie nach dem Prüfen des Zeitraums einen Stapel. Der Status zeigt den tatsächlichen Verarbeitungsstand.</p>{/if}{#if record.import_confirmed_at}<p class="small mt">Kanzlei-Import bestätigt am {display(record.import_confirmed_at,'created_at')}.</p>{/if}</div>{#if exportItems.length}<div class="table-scroll"><table class="data-table"><thead><tr><th>Beleg</th><th class="number">Betrag</th><th>Konto</th><th>Gegenkonto</th><th>Steuerschlüssel</th></tr></thead><tbody>{#each exportItems as item}<tr><td>{#if sourceUrl(item)}<a class="text-link" href={sourceUrl(item)}>{sourceName(item)}<Icon name="arrow" size={13}/></a>{:else}{sourceName(item)}{/if}</td><td class="number">{currencyAmount(item.amount,item.currency||'EUR')}</td><td>{item.account||'—'}</td><td>{item.counter_account||'—'}</td><td>{item.tax_key||'—'}</td></tr>{/each}</tbody></table></div>{/if}</section>{/if}
  {#if slug==='dunning'}<section class="panel"><header class="panel-header"><div><h2>Erinnerungen & Nachweise</h2><p>Jede erstellte Stufe bleibt mit ihrem damaligen Inhalt erhalten.</p></div></header><div class="panel-body">{#if record.blocked}<div class="notice warning"><Icon name="lock"/><div>Das Mahnverfahren ist gesperrt. Prüfen Sie die Begründung, bevor Sie einen weiteren Schritt freigeben.</div></div>{/if}{#each dunningEvents as event}<article class="timeline-item"><h3>{Number(event.stage)>1?'Mahnstufe '+event.stage:'Zahlungserinnerung'}</h3><p>{display(event.created_at,'created_at')}</p>{#if event.snapshot?.due_date||event.snapshot?.next_due_date}<p>Gesetzte Frist: {display(event.snapshot.next_due_date||event.snapshot.due_date,'date')}</p>{/if}{#if event.document_id}<a class="btn small mt" href={`/api/v1/documents/${event.document_id}/download`} data-sveltekit-reload download><Icon name="download" size={15}/>PDF dieser Erinnerung herunterladen</a>{:else}<p class="field-help mt">Der PDF-Nachweis wird noch verarbeitet.</p>{/if}</article>{/each}{#if !dunningEvents.length}<p class="small">Noch keine Erinnerung erstellt. Prüfen Sie Forderung, Fälligkeit, bestätigte Gebühren und etwaige Mahnsperren vor dem ersten Schritt.</p>{/if}<p class="field-help mt">Ein erzeugtes PDF wird nicht automatisch an den Kunden gesendet. Einen Versand geben Sie im vorgesehenen Kommunikationsbereich ausdrücklich frei.</p></div></section>{/if}
{/if}
<style>.bank-transaction{display:flex;align-items:center;justify-content:space-between;gap:24px;padding:22px 26px}.bank-transaction+.bank-transaction{border-top:1px solid var(--line)}.bank-transaction>div:first-child{min-width:0}.bank-transaction strong{font-size:14px;font-weight:500}.bank-transaction p{margin:6px 0 9px;overflow-wrap:anywhere}.bank-transaction-total{display:flex;align-items:center;gap:18px;white-space:nowrap;flex:none}@media(max-width:760px){.bank-transaction{padding:20px;align-items:flex-start;flex-direction:column;gap:14px}.bank-transaction-total{width:100%;justify-content:space-between}.bank-transaction strong{font-size:15px}}</style>
